import{_ as e,o as s,c as o,a2 as a}from"./chunks/framework.CvydjLy7.js";const g=JSON.parse('{"title":"二、4.x 相对 3.x 变了什么","description":"","frontmatter":{"title":"二、4.x 相对 3.x 变了什么"},"headers":[{"level":3,"title":"2.1 starter 改名（附官方原文）","slug":"_2-1-starter-改名-附官方原文","link":"#_2-1-starter-改名-附官方原文","children":[]},{"level":3,"title":"2.2 从整体式走向模块化","slug":"_2-2-从整体式走向模块化","link":"#_2-2-从整体式走向模块化","children":[]},{"level":3,"title":"2.3 Jackson 升到 3.x","slug":"_2-3-jackson-升到-3-x","link":"#_2-3-jackson-升到-3-x","children":[]},{"level":3,"title":"2.4 其他值得注意的搬迁项","slug":"_2-4-其他值得注意的搬迁项","link":"#_2-4-其他值得注意的搬迁项","children":[]},{"level":3,"title":"2.5 升级自查清单","slug":"_2-5-升级自查清单","link":"#_2-5-升级自查清单","children":[]}],"relativePath":"ch00/02.md","filePath":"ch00/02.md","lastUpdated":1789497795000}'),r={name:"ch00/02.md"};function i(d,t,n,c,p,l){return s(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="二、4-x-相对-3-x-变了什么" tabindex="-1">二、4.x 相对 3.x 变了什么 <a class="header-anchor" href="#二、4-x-相对-3-x-变了什么" aria-label="Permalink to &quot;二、4.x 相对 3.x 变了什么&quot;">​</a></h1><p>这是本篇的核心内容。Spring Boot 4.0 是一次大版本升级，做了两件影响面很大的事：<strong>把原来一个巨型 jar 拆成了一批细粒度模块</strong>，以及<strong>把 Jackson 升到了 3.x</strong>。这两件事直接导致大量 3.x 写法失效。</p><p>下面这张表里的每一条我都实际验证过，验证方式写在备注里，你可以自己复核。</p><h3 id="_2-1-starter-改名-附官方原文" tabindex="-1">2.1 starter 改名（附官方原文） <a class="header-anchor" href="#_2-1-starter-改名-附官方原文" aria-label="Permalink to &quot;2.1 starter 改名（附官方原文）&quot;">​</a></h3><p>官方文档的 starter 清单里，被废弃的条目会在描述末尾标注 “deprecated in favor of ...”。以下是从 <a href="https://docs.spring.io/spring-boot/reference/using/build-systems.html" target="_blank" rel="noreferrer">Build Systems</a> 页面提取的原文：</p><table tabindex="0"><thead><tr><th>旧坐标（已废弃）</th><th>新坐标</th><th>官方描述原文</th></tr></thead><tbody><tr><td><code>spring-boot-starter-web</code></td><td><code>spring-boot-starter-webmvc</code></td><td>Starter for building web, including RESTful, applications using Spring MVC. Uses Tomcat as the default embedded container <strong>(deprecated in favor of spring-boot-starter-webmvc)</strong></td></tr><tr><td><code>spring-boot-starter-web-services</code></td><td><code>spring-boot-starter-webservices</code></td><td>Starter for using Spring Web Services <strong>(deprecated in favor of spring-boot-starter-webservices)</strong></td></tr><tr><td><code>spring-boot-starter-oauth2-client</code></td><td><code>spring-boot-starter-security-oauth2-client</code></td><td>Starter for using Spring Security&#39;s OAuth2/OpenID Connect client features <strong>(deprecated in favor of spring-boot-starter-security-oauth2-client)</strong></td></tr><tr><td><code>spring-boot-starter-oauth2-resource-server</code></td><td><code>spring-boot-starter-security-oauth2-resource-server</code></td><td>同上规律：OAuth2 相关 starter 统一加 <code>security-</code> 前缀</td></tr><tr><td><code>spring-boot-starter-oauth2-authorization-server</code></td><td><code>spring-boot-starter-security-oauth2-authorization-server</code></td><td>同上规律</td></tr></tbody></table><blockquote><p><strong>注意：废弃不等于不可用</strong></p><p>废弃的坐标仍然可以正常下载和运行（我在 Maven 中央仓库逐个探测过，<code>spring-boot-starter-web</code> 在 4.1.1 下依然返回 HTTP 200）。它们存在只是为了兼容存量项目。新写的代码请用新坐标 —— 这样将来大版本清理时不用改。</p></blockquote><blockquote><p><strong>澄清一个流传很广的错误说法</strong></p><p>网上有文章说 <code>spring-boot-starter-amqp</code> 改名成了 <code>spring-boot-starter-rabbitmq</code>。我实际探测的结果是：<strong><code>spring-boot-starter-rabbitmq</code> 返回 HTTP 404，这个坐标根本不存在</strong>；而 <code>spring-boot-starter-amqp</code> 在 4.1.1 下正常存在，官方描述是 “Starter for using Spring AMQP and Rabbit MQ”，也没有 deprecated 标记。用消息队列时请继续使用 <code>spring-boot-starter-amqp</code>。</p><p>这件事的教训是：判断一个坐标有没有改名，别信二手文章，去看它的 pom 文件里有没有 deprecated 字样，或者直接查官方 starter 清单表。</p></blockquote><h3 id="_2-2-从整体式走向模块化" tabindex="-1">2.2 从整体式走向模块化 <a class="header-anchor" href="#_2-2-从整体式走向模块化" aria-label="Permalink to &quot;2.2 从整体式走向模块化&quot;">​</a></h3><p>3.x 时代，Spring Boot 的功能集中在一批大 jar 里；4.x 按功能拆成了许多小模块，每个模块可以单独引入。这带来两个直接变化。</p><p>**变化一：新增大量 <code>-test</code> 后缀的测试 starter。**以前写 Web 层测试，引入一个庞大的 <code>spring-boot-starter-test</code>；现在可以只引你需要的那个。以下是本教程会用到的几个：</p><table tabindex="0"><thead><tr><th>starter</th><th>用途</th></tr></thead><tbody><tr><td><code>spring-boot-starter-webmvc-test</code></td><td>测试 Spring MVC 与 Tomcat（提供 <code>@WebMvcTest</code>、<code>@AutoConfigureMockMvc</code>）</td></tr><tr><td><code>spring-boot-starter-data-jpa-test</code></td><td>测试 JPA 相关自动配置</td></tr><tr><td><code>spring-boot-starter-security-test</code></td><td>测试 Spring Security（提供 <code>@WithMockUser</code> 等）</td></tr><tr><td><code>spring-boot-starter-actuator-test</code></td><td>测试 Actuator 端点</td></tr><tr><td><code>spring-boot-starter-test</code></td><td>核心测试支持，JUnit Jupiter、AssertJ、Mockito 都在这里</td></tr></tbody></table><p>**变化二：属性/类的包名跟着模块走。**原来 <code>org.springframework.boot.autoconfigure.*</code> 下的自动配置类，现在按模块重新分包。举两个例子：</p><table tabindex="0"><thead><tr><th>类或注解</th><th>3.x 包名</th><th>4.x 包名</th></tr></thead><tbody><tr><td><code>@AutoConfigureMockMvc</code></td><td><code>org.springframework.boot.test.autoconfigure.web.servlet</code></td><td><code>org.springframework.boot.webmvc.test.autoconfigure</code></td></tr><tr><td><code>DataSourceAutoConfiguration</code></td><td><code>org.springframework.boot.autoconfigure.jdbc</code></td><td><code>org.springframework.boot.jdbc.autoconfigure</code></td></tr><tr><td><code>@SpringBootTest</code></td><td>包名未变，仍是 <code>org.springframework.boot.test.context</code></td><td></td></tr></tbody></table><blockquote><p><strong>最典型的报错长这样</strong></p><p>从 3.x 项目里拷过来一段测试代码，编译时提示：</p><p><strong>编译错误</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">error:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.springframework.boot.test.autoconfigure.web.servlet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> does</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> not</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exist</span></span></code></pre></div><p>类名没变、方法没变，只是包名换了。<strong>遇到“类找不到”先怀疑包名迁移，而不是怀疑依赖没引</strong>。查找正确包名最快的办法是解压 jar 搜类名：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.m2/repository/org/springframework/boot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;spring-boot-webmvc-test-4.1.1.jar&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AutoConfigureMockMvc</span></span></code></pre></div></blockquote><h3 id="_2-3-jackson-升到-3-x" tabindex="-1">2.3 Jackson 升到 3.x <a class="header-anchor" href="#_2-3-jackson-升到-3-x" aria-label="Permalink to &quot;2.3 Jackson 升到 3.x&quot;">​</a></h3><p>Spring Framework 7 把 JSON 处理库换成了 Jackson 3，核心包名发生了迁移：</p><table tabindex="0"><thead><tr><th>内容</th><th>Jackson 2（3.x 时代）</th><th>Jackson 3（4.x 时代）</th></tr></thead><tbody><tr><td><code>ObjectMapper</code></td><td><code>com.fasterxml.jackson.databind</code></td><td><code>tools.jackson.databind</code></td></tr><tr><td>核心包</td><td><code>com.fasterxml.jackson.core</code></td><td><code>tools.jackson.core</code></td></tr><tr><td><strong>注解包</strong></td><td><code>com.fasterxml.jackson.annotation</code></td><td><strong>保持不变</strong></td></tr></tbody></table><p>这一点在本机工程的依赖树里可以直接看到 —— 注意 <code>groupId</code> 的差别：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[INFO]    +- org.springframework.boot:spring-boot-starter-jackson:jar:4.1.1:compile</span></span>
<span class="line"><span>[INFO]    |  \\- org.springframework.boot:spring-boot-jackson:jar:4.1.1:compile</span></span>
<span class="line"><span>[INFO]    |     \\- tools.jackson.core:jackson-databind:jar:3.1.5:compile</span></span>
<span class="line"><span>[INFO]    |        +- com.fasterxml.jackson.core:jackson-annotations:jar:2.21:compile</span></span>
<span class="line"><span>[INFO]    |        \\- tools.jackson.core:jackson-core:jar:3.1.5:compile</span></span></code></pre></div><p>顺带一个观察：注解包不仅包名没变，连版本号也还留在 2.x 线上（<code>2.21</code>），而 <code>databind</code> 与 <code>core</code> 已经是 3.1.5。</p><p>好消息是注解包没动 —— <code>@JsonProperty</code>、<code>@JsonFormat</code>、<code>@JsonIgnore</code> 这些日常用的注解 import 不用改；坏消息是如果你手写过 <code>ObjectMapper</code> 的配置代码，import 必须改。</p><p>更需要注意的是配置项的语义变化。Jackson 3 把日期时间相关的开关从 <code>SerializationFeature</code> 挪到了 <code>DateTimeFeature</code>，而 Spring Boot 4.1 的 <code>JacksonProperties</code> 并没有暴露对应配置项。于是这段 3.x 时代的经典配置会直接让应用启动失败：</p><p><code>❌ 4.x 下会启动失败</code></p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  jackson</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    serialization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      write-dates-as-timestamps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 报错：No enum constant tools.jackson.databind.SerializationFeature.write-dates-as-timestamps</span></span></code></pre></div><p>正确做法是删掉它 —— Jackson 3 默认已输出 ISO-8601 字符串，本来就不需要这行配置。</p><h3 id="_2-4-其他值得注意的搬迁项" tabindex="-1">2.4 其他值得注意的搬迁项 <a class="header-anchor" href="#_2-4-其他值得注意的搬迁项" aria-label="Permalink to &quot;2.4 其他值得注意的搬迁项&quot;">​</a></h3><p>下面这几项经常被二手文章写成“已废弃”，实际情况是<strong>换了模块或包名，类本身没有标记 <code>@Deprecated</code></strong>。区别很重要：只换包名的话，按报错改 import 即可；真废弃的话才需要考虑迁移。</p><table tabindex="0"><thead><tr><th>项目</th><th>变化</th><th>实测核实</th></tr></thead><tbody><tr><td><code>RestTemplate</code></td><td>保留原包 <code>org.springframework.web.client</code>，<strong>未被标记 <code>@Deprecated</code></strong></td><td>反编译 <code>spring-web-7.0.9</code> 后 <code>javap -v</code> 查不到 Deprecated 标记；官方措辞是“经典方式”，建议新代码用 <code>RestClient</code></td></tr><tr><td><code>TestRestTemplate</code></td><td>从 <code>org.springframework.boot.test.web.client</code> 迁到 <code>org.springframework.boot.resttestclient</code>（独立模块 <code>spring-boot-resttestclient</code>），<strong>也未标记 <code>@Deprecated</code></strong></td><td>4.1.1 的 <code>spring-boot-test</code> 里已经找不到这个类；<code>RestTestClient</code> 在 Spring Framework 侧提供（<code>org.springframework.test.web.servlet.client</code>）</td></tr><tr><td><code>management.tracing.enabled</code></td><td>改为 <code>management.tracing.export.enabled</code></td><td>配错会导致追踪数据不上报</td></tr><tr><td>Apache Derby 集成</td><td>自动配置已移除</td><td>改用 H2 或外部数据库</td></tr></tbody></table><blockquote><p><strong>核实方法</strong>：判断一个类“到底废没废”，看它的字节码里有没有 <code>Deprecated</code> 标记，比读任何二手文章都可靠：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spring-web-7.0.9.jar</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RestTemplate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">javap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org/springframework/web/client/RestTemplate.class</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Deprecated</span></span></code></pre></div><p>输出为空就是没废弃。这个方法在本教程后面还会反复用到。</p></blockquote><h3 id="_2-5-升级自查清单" tabindex="-1">2.5 升级自查清单 <a class="header-anchor" href="#_2-5-升级自查清单" aria-label="Permalink to &quot;2.5 升级自查清单&quot;">​</a></h3><p>如果你手上有一个 3.x 项目要升级，按这个顺序过一遍能覆盖九成以上的报错：</p><ol><li><strong>换父 POM 版本</strong> <code>&lt;parent&gt;</code> 的版本改成 <code>4.1.1</code>，同时确认 <code>java.version</code> 不低于 17。</li><li><strong>替换废弃 starter</strong> 用 <code>spring-boot-starter-webmvc</code> 替换 <code>spring-boot-starter-web</code>；OAuth2 相关的加 <code>security-</code> 前缀；Web Services 用 <code>webservices</code>。</li><li><strong>修测试 import</strong> 所有 <code>@AutoConfigureMockMvc</code>、<code>@WebMvcTest</code> 的 import 改成 <code>org.springframework.boot.webmvc.test.autoconfigure.*</code>，并在 pom 里补上 <code>spring-boot-starter-webmvc-test</code>。</li><li><strong>清理 Jackson 配置</strong> 删掉 <code>spring.jackson.serialization.write-dates-as-timestamps</code>；<code>LocalDateTime</code> 的格式改用字段上的 <code>@JsonFormat</code>。</li><li><strong>编译，按报错逐个修包名</strong> 类找不到时，优先用解压 jar 搜类名的办法定位新包名，而不是改依赖。</li><li><strong>跑测试，确认行为差异</strong> 测试栈跨了大版本（JUnit Jupiter 6、Mockito 5.23），少数断言写法可能有差异。</li></ol>`,33)])])}const k=e(r,[["render",i]]);export{g as __pageData,k as default};
